/**
 * Interview Harvest -- Daily curated phrases from MLB/sports interviews
 * 1 interview / day -- 10 athlete expressions + 5 interviewer question patterns
 *
 * Why this exists separate from Podcast Harvest:
 *   - Athletes speak in a totally different register (clichés, humility, in-the-moment)
 *   - Interviewer question structures are GOLD for learners
 *     (Walk me through... / Talk about... / What did you see when... etc.)
 *   - Spoken English under pressure, not curated podcast banter
 *
 * Source: MLB Network, team beat reporters, post-game pressers, in-game booth interviews
 *
 * NOTE on -ing forms: All entries use FULL -ing forms (grinding, working, looking)
 * not g-dropped forms (grindin', workin', lookin') per project rule
 * (PP search compatibility -- feedback-no-g-dropping.md)
 */

import { JULY_GEN_SOURCES, JULY_GEN_ENTRIES, JULY_GEN_QUESTIONS } from './interview-july-generated';
import { AUGUST_GEN_SOURCES, AUGUST_GEN_ENTRIES, AUGUST_GEN_QUESTIONS } from './interview-august-generated';
import { SEPTEMBER_GEN_SOURCES, SEPTEMBER_GEN_ENTRIES, SEPTEMBER_GEN_QUESTIONS } from './interview-september-generated';
import { OCTOBER_GEN_SOURCES, OCTOBER_GEN_ENTRIES, OCTOBER_GEN_QUESTIONS } from './interview-october-generated';
import { NOVEMBER_GEN_SOURCES, NOVEMBER_GEN_ENTRIES, NOVEMBER_GEN_QUESTIONS } from './interview-november-generated';

export interface InterviewSource {
    date: string;
    show: string;            // "Padres Postgame", "MLB Network", etc.
    title: string;
    athlete: string;         // "Xander Bogaerts (SS, Padres)"
    interviewer?: string;    // "AJ Cassavell" など (任意)
    sport: string;           // ジャンルバッジ: 'MLB' | 'NBA' | 'Talk' | 'Music' | 'Tech' など自由ラベル
    youtubeId: string;
    url: string;
    tagline: string;
}

export interface InterviewEntry {
    daySlot: number;
    expression: string;
    contextBefore: string;
    target: string;
    contextAfter: string;
    note: string;
    rank: 'S' | 'A' | 'B' | 'C';
    month?: string;
}

/**
 * Interviewer question pattern -- 質問者の構文を抜き出す
 * これがこのページの podcast との最大の差別化ポイント
 */
export interface InterviewerQuestion {
    daySlot: number;
    pattern: string;          // "Walk me through..." みたいな型
    fullQuestion: string;     // 実際の質問全文
    askedAfter?: string;      // どんな展開のあとに来た質問か（文脈）
    note: string;             // とにお解説（なぜこの聞き方が使えるか）
    technique: 'open-ended' | 'walk-through' | 'reaction' | 'reflection' | 'comparison' | 'specific-moment' | 'follow-up';
    month?: string;
}

